import{_ as t,o as s,c as l,a3 as n}from"./chunks/framework.qCVWde4n.js";const b=JSON.parse('{"title":"卸载与还原","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/uninstall.md","filePath":"deploy/uninstall.md","lastUpdated":1791133906000}'),i={name:"deploy/uninstall.md"};function d(e,a,o,r,p,c){return s(),l("div",null,[...a[0]||(a[0]=[n(`<h1 id="卸载与还原" tabindex="-1">卸载与还原 <a class="header-anchor" href="#卸载与还原" aria-label="Permalink to &quot;卸载与还原&quot;">​</a></h1><p>不喜欢、出问题了、或者想回到纯净状态 —— 本篇讲怎么干净地退回去。</p><h2 id="先想清楚你要回退到哪" tabindex="-1">先想清楚你要回退到哪 <a class="header-anchor" href="#先想清楚你要回退到哪" aria-label="Permalink to &quot;先想清楚你要回退到哪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你想要的</th><th>做法</th><th>存档</th></tr></thead><tbody><tr><td>不要 Mod 能力，但要汉化</td><td>装回 <code>final_full_cn.apk</code>（覆盖安装）</td><td>保留</td></tr><tr><td>要完全纯净，回到英文原版</td><td>装回英文原版 APK</td><td>需先备份</td></tr><tr><td>只是不想要某个 Mod</td><td>在「Mod」页禁用它</td><td>保留</td></tr><tr><td>只是不想要某几项改动</td><td>在「参数」页「恢复默认」</td><td>保留</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">大多数情况不需要卸载</p><p><strong>如果只是不想要某个 Mod 或某项改动，根本不用卸载。</strong></p><ul><li>单个 Mod：面板 → 「Mod」页 → 点「禁用」（保留文件，下次想用再启用）</li><li>全部参数改动：面板 → 「参数」页 → 「恢复默认」（一键清空所有参数偏离）</li></ul><p>这两个操作都比卸载安全得多，而且随时可以反悔。</p></div><h2 id="场景一-退回纯汉化版" tabindex="-1">场景一：退回纯汉化版 <a class="header-anchor" href="#场景一-退回纯汉化版" aria-label="Permalink to &quot;场景一：退回纯汉化版&quot;">​</a></h2><p>想保留汉化，但不要 Mod 能力：</p><ol><li>下载 <code>final_full_cn.apk</code>。</li><li>直接点击安装 → 系统会提示「已存在同名应用，是否替换」→ 确定。</li><li>安装后启动，悬浮窗消失 = 框架已移除。</li></ol><p><strong>存档不受影响。</strong> 你之前用框架改过的存档数据（比如改过的威望）<strong>会保留</strong>，因为存档是独立文件。</p><div class="warning custom-block"><p class="custom-block-title">但改过的存档不会自动恢复</p><p>比如你用「存档页」把威望改成了 100 万，退回纯汉化版后威望<strong>还是 100 万</strong>。框架只负责改，不负责回滚。想恢复得在改之前自己记原值，或者用游戏自己的机制。</p></div><h2 id="场景二-完全还原到英文原版" tabindex="-1">场景二：完全还原到英文原版 <a class="header-anchor" href="#场景二-完全还原到英文原版" aria-label="Permalink to &quot;场景二：完全还原到英文原版&quot;">​</a></h2><ol><li><p><strong>先备份存档</strong>（重要）：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Android/data/&lt;游戏包名&gt;/files/rncampaignInfo.dat</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>复制到别的地方。</p></li><li><p>卸载当前的游戏（设置 → 应用 → 找到游戏 → 卸载）。</p><div class="danger custom-block"><p class="custom-block-title">卸载会清掉数据</p><p>卸载会连 <code>Android/data/&lt;包名&gt;/</code> 一起删除。所以<strong>必须先备份</strong>。</p></div></li><li><p>安装英文原版 APK（<code>eb3cdae*.apk</code>）。</p></li><li><p>如果需要，把备份的存档放回原位置。</p></li></ol><h2 id="场景三-只清理-mod-相关内容" tabindex="-1">场景三：只清理 Mod 相关内容 <a class="header-anchor" href="#场景三-只清理-mod-相关内容" aria-label="Permalink to &quot;场景三：只清理 Mod 相关内容&quot;">​</a></h2><p>想保留框架，但把 Mod 文件清干净：</p><p>进入 <code>Android/data/&lt;游戏包名&gt;/files/</code>：</p><table tabindex="0"><thead><tr><th>删什么</th><th>效果</th></tr></thead><tbody><tr><td><code>mods/</code> 下所有子文件夹</td><td>所有 Mod 失效（等于回到无 Mod 状态）</td></tr><tr><td><code>AFMOD_settings.json</code></td><td>面板设置重置（位置回默认）</td></tr><tr><td><code>AFMOD_log.txt</code></td><td>历史日志清空</td></tr><tr><td><strong>不要删</strong> <code>rncampaignInfo.dat</code></td><td>这是游戏存档！</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">更安全的做法</p><p>删文件有风险（删错就麻烦）。建议改用面板操作：</p><ul><li>想清空所有 Mod → 「Mod」页逐个禁用或删除</li><li>想清空所有参数改动 → 「参数」页「恢复默认」</li><li>想重置整个框架 → 「Mod」页底部「重置整个 Mod 系统」（保留你自己的自制 Mod）</li></ul></div><h2 id="场景四-框架本身出问题了" tabindex="-1">场景四：框架本身出问题了 <a class="header-anchor" href="#场景四-框架本身出问题了" aria-label="Permalink to &quot;场景四：框架本身出问题了&quot;">​</a></h2><p>如果游戏因为框架而打不开或频繁闪退：</p><p><strong>先自救</strong>（可能只是某个 Mod 的配置有错）：</p><ol><li>如果还能进游戏：面板 → 「Mod」页 → 逐个禁用，找出问题那个。</li><li>如果完全进不去：用文件管理器把 <code>mods/</code> 下的子文件夹<strong>临时改名</strong>（比如加个下划线前缀），框架就不会加载它们。能进游戏后再逐个排查。</li></ol><p><strong>还不行就覆盖安装</strong>：</p><p>装回 <code>final_full_cn.apk</code>，即可回到无框架状态，存档保留。</p><h2 id="存档备份的正确姿势" tabindex="-1">存档备份的正确姿势 <a class="header-anchor" href="#存档备份的正确姿势" aria-label="Permalink to &quot;存档备份的正确姿势&quot;">​</a></h2><p>无论哪种回退，都建议先备份存档：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 备份</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Android/data/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;游戏包名&gt;/files/rncampaignInfo.dat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        ↓</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 复制到</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/sdcard/我的备份/rncampaignInfo_日期.dat</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 恢复</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">把文件复制回原位置，覆盖同名文件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">建议在「没改过任何东西」的时候也备一份</p><p>这样如果以后改乱了，可以回到「干净起点」。</p></div><h2 id="一个提醒" tabindex="-1">一个提醒 <a class="header-anchor" href="#一个提醒" aria-label="Permalink to &quot;一个提醒&quot;">​</a></h2><p>框架对存档的改动<strong>只通过游戏自带的保存接口</strong>，不直接改文件字节。这意味着：</p><ul><li>改过的存档<strong>仍然是游戏能正常读的格式</strong>（不会因为格式不对而读不出）。</li><li>但改动<strong>是永久的</strong> —— 框架不回滚，需要你自己在改之前记录原值。</li></ul><p>「存档」页里改威望/回合之前，建议先看一眼当前值（页面上会显示），心里有个数。</p>`,31)])])}const u=t(i,[["render",d]]);export{b as __pageData,u as default};
